-- Phase 537 tests (UNION-9: 32 shared functions carry the merged text). TEST DATABASE ONLY (a local throwaway Postgres built from the owner paste chain, tests/sql/run_all_union.sh). Prints PASS / FAIL per check.
-- Test users and items are neutral test_* ids. Run on the final database (needs phase539 for the audit, so it checks the md5 itself).
\set ON_ERROR_STOP off
\set o '00000000-0000-0000-0000-00000000f537'
create schema if not exists t537;
create table if not exists t537.res (name text, ok boolean);
truncate t537.res;
create or replace function t537.chk(p_name text, p_ok boolean) returns void language plpgsql as $$
begin insert into t537.res values (p_name, coalesce(p_ok, false)); raise notice '% %', case when coalesce(p_ok, false) then 'PASS' else 'FAIL' end, p_name; end $$;
create or replace function t537.def(p_sig text) returns text language sql as $$ select pg_get_functiondef(p_sig::regprocedure) $$;
create or replace function t537.has(p_sig text, p_text text) returns boolean language sql as $$ select position(p_text in pg_get_functiondef(p_sig::regprocedure)) > 0 $$;

\echo == T1 every function of this file has the merged text (the md5 is recorded by phase539; this suite runs on the final database)
select t537.chk('T1a all 32 functions exist', (select count(*) = 32 from unnest(array['public.location_save(integer,jsonb)', 'public.login_failed(text)', 'public.loyalty_award(uuid)', 'public.notify_cancel(bigint)', 'public.notify_enqueue(uuid,uuid,text,text,jsonb,text,text,text)', 'public.notify_optin_set(uuid,text,boolean,text,text)', 'public.notify_outbox_summary()', 'public.online_order_get(uuid)', 'public.online_order_save(uuid,uuid,integer,text,text,text,text,jsonb,text,text,date,numeric,numeric,numeric,text,text,text)', 'public.online_orders_list(integer,text,date,date,integer)', 'public.packaging_set(uuid,uuid,numeric,text,boolean,text)', 'public.partner_calculate(bigint,date,date,jsonb)', 'public.partner_settlement_save(bigint,date,date,jsonb,text,uuid)', 'public.path_cfg(text,integer)', 'public.pay_supplier(uuid,integer,jsonb,uuid,text)', 'public.payment_intent_link(bigint,bigint)', 'public.pool_set(integer,date,text,numeric,text,boolean,text,uuid)', 'public.production_can_make(integer)', 'public.production_post(integer,uuid,numeric,uuid,timestamp with time zone,text,numeric)', 'public.production_preview(integer,uuid,numeric)', 'public.production_run_costs(integer,date,date)', 'public.production_void(uuid,text)', 'public.profit_source_check(date,date,integer)', 'public.purchase_get(uuid)', 'public.recipe_approve(uuid,text)', 'public.recipe_book(integer,boolean,integer)', 'public.recipe_copy(uuid,uuid,boolean,uuid)', 'public.recipe_cost(uuid,integer)', 'public.recipe_cost_component_set(uuid,text,text,numeric,numeric,text,text,uuid)', 'public.recipe_save(uuid,uuid,numeric,text,text,jsonb,uuid,boolean)', 'public.recipe_steps_save(uuid,jsonb,uuid)', 'public.recipe_yield_suggestion(uuid)']) f where to_regprocedure(f) is not null));
